import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import vm from 'node:vm';
import {pathToFileURL} from 'node:url';
const input=JSON.parse(process.argv[1]),sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const blob=x=>crypto.createHash('sha1').update(Buffer.concat([Buffer.from('blob '+x.length+'\0'),x])).digest('hex');
const file=path.join(input.root,input.path),bytes=fs.readFileSync(file);
assert.equal(sha(bytes),input.sha256);assert.equal(blob(bytes),input.gitBlob);
assert.equal(sha(fs.readFileSync(input.module)),input.moduleSHA256);
const imported=await import(pathToFileURL(input.module).href),api=typeof imported.build==='function'?imported:imported.default;
assert.equal(api.version,'0.27.3');
const buildOptions={absWorkingDir:input.root,entryPoints:[input.path],bundle:true,write:false,metafile:true,format:'iife',globalName:'WorldlawJobDiagnostic',platform:'browser',target:['es2022'],charset:'utf8',legalComments:'inline',minify:false,sourcemap:false,logLevel:'silent'};
let build;try{build=await api.build({...buildOptions,plugins:[{name:'exact-job-source',setup(b){b.onLoad({filter:/\.mjs$/,namespace:'file'},({path:p})=>{assert.equal(p,file);return{contents:bytes.toString('utf8'),loader:'js',resolveDir:path.dirname(p)};});}}]});}finally{api.stop();}
assert.equal(build.outputFiles.length,1);assert.deepEqual(Object.keys(build.metafile.inputs),[input.path]);
assert(build.warnings.some(x=>x.id==='empty-import-meta'));
const sentinel=new Error('SENTINEL_WORKER_CONSTRUCTOR_REACHED');
let esmCalls=0,esmTarget=null,esmOptions=null;
const previous=Object.getOwnPropertyDescriptor(globalThis,'Worker');
const {startReturnBounds}=await import(pathToFileURL(file).href);
let esmError;
try{
 Object.defineProperty(globalThis,'Worker',{configurable:true,writable:true,value:class{constructor(url,options){esmCalls++;esmTarget=url;esmOptions=options;throw sentinel;}}});
 try{startReturnBounds({schema:'source'});}catch(error){esmError=error;}
}finally{if(previous)Object.defineProperty(globalThis,'Worker',previous);else delete globalThis.Worker;}
assert.equal(esmCalls,1);assert.equal(esmError,sentinel);assert.equal(esmOptions.type,'module');
assert.equal(esmTarget.href,new URL('./equal-angle-bounds-worker.mjs',pathToFileURL(file)).href);
let iifeCalls=0,iifeError;
const context=vm.createContext({URL,Worker:class{constructor(){iifeCalls++;throw sentinel;}}});
vm.runInContext(build.outputFiles[0].text,context,{timeout:1000});
try{vm.runInContext("WorldlawJobDiagnostic.startReturnBounds({schema:'source'})",context,{timeout:1000});}catch(error){iifeError=error;}
assert.equal(iifeCalls,0);assert(iifeError);assert.equal(iifeError.code,'ERR_INVALID_URL');assert.equal(iifeError.name,'TypeError');
assert.equal(sha(fs.readFileSync(file)),input.sha256);
assert.equal(sha(fs.readFileSync(input.module)),input.moduleSHA256);
const receipt={kind:'native-pre-worker-url-construction-control',node:process.version,esbuild:api.version,source:{path:input.path,gitBlob:input.gitBlob,sha256:input.sha256},runnerSHA256:sha(process.execArgv[process.execArgv.indexOf('-e')+1]),scope:'Exact existing job module compiled with maintained browser/IIFE/ES2022 options plus a diagnostic globalName to expose its export. Native WHATWG URL with a sentinel Worker constructor; no worker or scientific calculation executes.',controls:{nativeESM:{constructorCalls:esmCalls,constructorReached:true,targetProtocol:esmTarget.protocol,targetProjectPath:'src/trajectory/equal-angle-bounds-worker.mjs',workerType:esmOptions.type,terminal:'sentinel deliberately stopped before creating a worker'},iife:{constructorCalls:iifeCalls,constructorReached:false,error:{name:iifeError.name,code:iifeError.code,message:iifeError.message},terminal:'relative worker URL construction fails before the Worker constructor'}},warnings:build.warnings.map(w=>({id:w.id,text:w.text,location:{file:w.location.file,line:w.location.line,column:w.location.column}})),checks:{nativeESMHasResolvableModuleBase:true,iifeFailsBeforeAnyWorkerConstructor:true,sourceAndCompilerUnchanged:true},compiledBytesHandling:'Diagnostic compiled bytes stayed in native process memory and are not emitted or saved.',limits:'No browser/DOM run, worker execution, cancellation course, scientific calculation, notebook replay or repair qualification. Existing main and composed source have identical job bytes; source equality is established separately.'};
build.outputFiles[0].contents.fill(0);build.outputFiles.length=0;
console.log(JSON.stringify(receipt));
